// UnicodeVersion is `unicode_segmentation::UNICODE_VERSION`:
// the version of [Unicode](http://www.unicode.org/)
// that this version of unicode-segmentation is based on.
var UnicodeVersion = rs.Tuple3[uint64, uint64, uint64]{F0: 17, F1: 0, F2: 0}

var tablesUnicodeVersionU8 = rs.Tuple3[uint8, uint8, uint8]{F0: 17, F1: 0, F2: 0}

// mod util

func tablesUtilBsearchRangeTable(c rune, r []rs.Tuple2[rune, rune]) bool {
	_, found := sliceBinarySearchBy(r, func(entry *rs.Tuple2[rune, rune]) int {
		lo, hi := entry.F0, entry.F1
		if lo <= c && c <= hi {
			return orderingEqual
		} else if hi < c {
			return orderingLess
		} else {
			return orderingGreater
		}
	})
	return found
}

func tablesUtilIsAlphabetic(c rune) bool {
	// The Rust toolchain Mjolnir is built with has the crate's Unicode
	// version (17.0.0), so this takes the first branch, the standard
	// library's table, as the Rust build does. The two tables hold the same
	// characters (TestStdAndCrateTablesAgree).
	if tablesUnicodeVersionU8 == strs.CharUnicodeVersion {
		return strs.IsAlphabetic(c)
	} else {
		switch {
		case (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'):
			return true
		case c > 0x7f:
			return tablesDerivedPropertyAlphabetic(c)
		default:
			return false
		}
	}
}

func tablesUtilIsNumeric(c rune) bool {
	if tablesUnicodeVersionU8 == strs.CharUnicodeVersion {
		return strs.IsNumeric(c)
	} else {
		switch {
		case c >= '0' && c <= '9':
			return true
		case c > 0x7f:
			return tablesGeneralCategoryN(c)
		default:
			return false
		}
	}
}

func tablesUtilIsAlphanumeric(c rune) bool {
	return tablesUtilIsAlphabetic(c) || tablesUtilIsNumeric(c)
}

// mod general_category

func tablesGeneralCategoryN(c rune) bool {
	return tablesUtilBsearchRangeTable(c, tablesGeneralCategoryNTable)
}

// mod derived_property

func tablesDerivedPropertyAlphabetic(c rune) bool {
	return tablesUtilBsearchRangeTable(c, tablesDerivedPropertyAlphabeticTable)
}

func tablesDerivedPropertyInCBExtend(c rune) bool {
	return tablesUtilBsearchRangeTable(c, tablesDerivedPropertyInCBExtendTable)
}

func tablesIsIncbLinker(c rune) bool {
	switch c {
	case 0x94D, 0x9CD, 0xACD, 0xB4D, 0xC4D, 0xD4D, 0x1039, 0x17D2, 0x1A60, 0x1B44, 0x1BAB, 0xA9C0, 0xAAF6,
		0x10A3F, 0x11133, 0x113D0, 0x1193E, 0x11A47, 0x11A99, 0x11F42:
		return true
	}
	return false
}

