func tablesGraphemeGraphemeCategory(c rune) (uint32, uint32, tablesGraphemeGraphemeCat) {
	// Perform a quick O(1) lookup in a precomputed table to determine
	// the slice of the range table to search in.
	const lookupInterval = 0x80
	idx := int(uint32(c) / lookupInterval)
	// If the `idx` is outside of the precomputed table - use the slice
	// starting from the last covered index in the precomputed table and
	// ending with the length of the range table.
	rangeStart, rangeEnd := 1612, 1618
	if idx+2 <= len(tablesGraphemeGraphemeCatLookup) {
		r := tablesGraphemeGraphemeCatLookup[idx : idx+2]
		rangeStart, rangeEnd = int(r[0]), int(r[1]+1)
	}

	// Compute pessimistic default lower and upper bounds on the category.
	// If character doesn't map to any range and there is no adjacent range
	// in the table slice - these bounds has to apply.
	lower := uint32(idx) * lookupInterval
	upper := lower + lookupInterval - 1
	return tablesGraphemeBsearchRangeValueTable(c, tablesGraphemeGraphemeCatTable[rangeStart:rangeEnd], lower, upper)
}

