// The helpers below stand in for parts of Rust's standard library that the
// crate's code uses and that go/rs does not provide yet.

// The results of a comparison function given to sliceBinarySearchBy:
// `core::cmp::Ordering`.
const (
	orderingLess    = -1
	orderingEqual   = 0
	orderingGreater = 1
)

// sliceBinarySearchBy is `<[T]>::binary_search_by` of Rust 1.99.1
// (core/src/slice/mod.rs): the index of an element for which f returns
// orderingEqual and true, or the index where one would be inserted and false.
func sliceBinarySearchBy[T any](slice []T, f func(*T) int) (int, bool) {
	size := len(slice)
	if size == 0 {
		return 0, false
	}
	base := 0

	// This loop intentionally doesn't have an early exit if the comparison
	// returns Equal. We want the number of loop iterations to depend *only*
	// on the size of the input slice so that the CPU can reliably predict
	// the loop count.
	for size > 1 {
		half := size / 2
		mid := base + half

		cmp := f(&slice[mid])
		if cmp != orderingGreater {
			base = mid
		}

		// This is imprecise in the case where `size` is odd and the
		// comparison returns Greater: the mid element still gets included
		// by `size` even though it's known to be larger than the element
		// being searched for.
		//
		// This is fine though: we gain more performance by keeping the
		// loop iteration count invariant (and thus predictable) than we
		// lose from considering one additional element.
		size -= half
	}

	cmp := f(&slice[base])
	if cmp == orderingEqual {
		return base, true
	}
	if cmp == orderingLess {
		return base + 1, false
	}
	return base, false
}

// strNextChar is `s.chars().next()`: the first character of s and its length
// in bytes; ok is false for an empty string. A Rust `str` is valid UTF-8; a
// byte of s that is not part of a valid encoding is read as U+FFFD with a
// length of one, as a Go range loop reads it.
func strNextChar(s string) (c rune, size int, ok bool) {
	if s == "" {
		return 0, 0, false
	}
	c, size = utf8.DecodeRuneInString(s)
	return c, size, true
}

// strNextBackChar is `s.chars().next_back()`: the last character of s and its
// length in bytes; ok is false for an empty string.
func strNextBackChar(s string) (c rune, size int, ok bool) {
	if s == "" {
		return 0, 0, false
	}
	c, size = utf8.DecodeLastRuneInString(s)
	return c, size, true
}
